        df_valid.sort_values('month')
        .groupby(['account_id', 'month'])['mrr']
        .last()
        .reset_index()
        .groupby('month')['mrr']
        .sum()
        .reset_index()
        .sort_values('month')
    )

    if len(monthly_mrr) >= 2:
        last_month_mrr = monthly_mrr.iloc[-1]['mrr']
        prev_month_mrr = monthly_mrr.iloc[-2]['mrr']
        last_month_label = monthly_mrr.iloc[-1]['month'].strftime('%Y-%m')
        prev_month_label = monthly_mrr.iloc[-2]['month'].strftime('%Y-%m')

        pct_change = ((last_month_mrr - prev_month_mrr) / prev_month_mrr) * 100 if prev_month_mrr != 0 else 0.0
        direction = 'up' if pct_change > 0.5 else ('down' if pct_change < -0.5 else 'flat')

        result['trends'].append({
            "column": "mrr",
            "period": "MoM",
            "direction": direction,
            "pct_change": round(pct_change, 4),
            "segment": None
        })

    by_plan = (
        df_valid.sort_values('month')
        .groupby(['plan', 'account_id', 'month'])['mrr']
        .last()
        .reset_index()
        .groupby(['plan', 'month'])['mrr']
        .sum()
        .reset_index()
        .sort_values('month')
    )

    for plan_val, grp in by_plan.groupby('plan'):
        grp = grp.sort_values('month')
        if len(grp) >= 2:
            lv = grp.iloc[-1]['mrr']
            pv = grp.iloc[-2]['mrr']
            pc = ((lv - pv) / pv) * 100 if pv != 0 else 0.0
            d = 'up' if pc > 0.5 else ('down' if pc < -0.5 else 'flat')
            result['trends'].append({
                "column": "mrr",
                "period": "MoM",
                "direction": d,
                "pct_change": round(pc, 4),
                "segment": str(plan_val)
            })

    result['assumptions'].append(
        "MRR per month = sum of each account_id's last mrr value in that month; only counted/netted rows used."
    )
    result['assumptions'].append(
        f"Last month is {last_month_label} (MRR={last_month_mrr:.2f}); prior month is {prev_month_label} (MRR={prev_month_mrr:.2f})."
    )

except Exception as e:
    result['trends'].append({
        "column": "mrr",
        "period": "MoM",
