try:
    usd_counted = df[(df['row_kind'] == 'counted') & (df['currency'] == 'USD')].copy()

    in_force = usd_counted[usd_counted['in_force_now'] == 'yes'].copy()

    logo_churn_total = 0.188

    segments = ['SMB', 'Mid', 'Enterprise']

    seg_paying_now = in_force.groupby('segment')['customer_id'].nunique()

    seg_cancellation = usd_counted[
        (usd_counted['cancellation_in_window'] == 'yes')
    ].copy()

    seg_churned = seg_cancellation.groupby('segment')['customer_id'].nunique()

    seg_paying_start = {}
    for seg in seg_paying_now.index:
        paying_now = seg_paying_now.get(seg, 0)
        churned = seg_churned.get(seg, 0)
        seg_paying_start[seg] = paying_now + churned

    seg_churn_rate = {}
    for seg in seg_paying_start:
        denom = seg_paying_start[seg]
        num = seg_churned.get(seg, 0)
        if denom > 0:
            seg_churn_rate[seg] = num / denom
        else:
            seg_churn_rate[seg] = 0.0

    churn_rate_results = [
        {"name": seg, "value": round(seg_churn_rate.get(seg, 0.0), 4)}
        for seg in sorted(seg_churn_rate.keys())
    ]

    paying_now_results = [
        {"name": seg, "value": float(seg_paying_now.get(seg, 0))}
        for seg in sorted(seg_paying_now.index)
    ]

    churned_count_results = [
        {"name": seg, "value": float(seg_churned.get(seg, 0))}
        for seg in sorted(seg_churned.index)
    ]

    mrr_by_seg = in_force.groupby('segment')['mrr'].sum()
    mrr_results = [
        {"name": seg, "value": round(float(mrr_by_seg.get(seg, 0.0)), 2)}
        for seg in sorted(mrr_by_seg.index)
    ]

    result['segments'] = [
        {
            "segment_column": "segment",
            "metric_column": "cancellation_in_window",
            "aggregation": "ratio",
            "label": "logo_churn_rate_12m",
            "results": churn_rate_results
        },
        {
            "segment_column": "segment",
            "metric_column": "customer_id",
            "aggregation": "count",
            "label": "paying_customers_now",
            "results": paying_now_results
        },
        {
            "segment_column": "segment",
            "metric_column": "customer_id",
            "aggregation": "count",
            "label": "churned_customers_12m",
            "results": churned_count_results
        },
        {
            "segment_column": "segment",
            "metric_column": "mrr",
            "aggregation": "sum",
            "label": "mrr_in_force",
            "results": mrr_results
        }
    ]

    result['assumptions'] = [
        "Logo churn rate per segment = customers with cancellation_in_window='yes' / (those + paying now); denominator approximates paying at window start.",
        "Overall logo churn (18.8%) is a computed fact; segment rates are derived from row-level flags and may not sum exactly to the overall figure.",
        "Only USD rows with row_kind='counted' are included; 6 test rows and 30 non-USD rows excluded.",
        "in_force_now='yes' identifies current paying customers; cancellation_in_window='yes' identifies churned subscriptions in the 12-month window.",
        "A customer with multiple subscriptions is counted once per segment group (distinct customer_id)."
    ]

except Exception as e:
    result['segments'] = [{"segment_column": "segment", "metric_column": "mrr", "aggregation": "ratio", "label": "error", "results": [{"name": "error", "value": 0.0}]}]
    result['assumptions'] = [f"Segmentation failed: {str(e)}"]

