import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # Monthly customer churn rate:
    # For each month M in the last 12 months:
    #   - customers active at end of month M-1 (base)
    #   - customers who were in base but NOT active at end of month M (churned)
    #   - churn rate = churned / base

    df['month_dt'] = pd.to_datetime(df['month'])

    # Use only counted rows (filter row_kind)
    df_valid = df[df['row_kind'] == 'counted'].copy()

    # Get all months sorted
    all_months = sorted(df_valid['month_dt'].unique())

    # Last 12 months
    last_12 = all_months[-12:] if len(all_months) >= 12 else all_months

    # For each month, get the set of active customers (mrr > 0)
    monthly_active = {}
    for m in all_months:
        snap = df_valid[df_valid['month_dt'] == m]
        # Each customer's latest snapshot in that month
        snap_last = snap.sort_values('month_dt').groupby('customer_id').last()
        active = set(snap_last[snap_last['mrr'] > 0].index)
        monthly_active[m] = active

    churn_results = []
    for i, m in enumerate(last_12):
        m_idx = all_months.index(m)
        if m_idx == 0:
            continue
        prev_m = all_months[m_idx - 1]
        base = monthly_active.get(prev_m, set())
        current = monthly_active.get(m, set())
        if len(base) == 0:
            continue
        churned = base - current
        churn_rate = len(churned) / len(base)
        period_label = m.strftime('%Y-%m')
        churn_results.append({
            "name": period_label,
            "value": round(churn_rate, 6)
        })

    result['segments'].append({
        "segment_column": "month",
        "metric_column": "customer_id",
        "aggregation": "ratio",
        "label": "monthly_logo_churn_rate",
        "results": churn_results
    })

    # Also break down by plan and segment for the last month
    last_month = last_12[-1] if last_12 else None
    if last_month is not None:
        prev_last = all_months[all_months.index(last_month) - 1] if all_months.index(last_month) > 0 else None

        if prev_last is not None:
            base_snap = df_valid[df_valid['month_dt'] == prev_last].groupby('customer_id').last()
            base_active = base_snap[base_snap['mrr'] > 0]

            curr_snap = df_valid[df_valid['month_dt'] == last_month].groupby('customer_id').last()
            curr_active_ids = set(curr_snap[curr_snap['mrr'] > 0].index)

            base_active = base_active.reset_index()

            for seg_col in ['plan', 'segment', 'country']:
                if seg_col not in base_active.columns:
                    continue
                seg_results = []
                for grp_val, grp_df in base_active.groupby(seg_col):
                    grp_ids = set(grp_df['customer_id'])
                    grp_churned = grp_ids - curr_active_ids
                    if len(grp_ids) == 0:
                        continue
                    rate = len(grp_churned) / len(grp_ids)
                    seg_results.append({"name": str(grp_val), "value": round(rate, 6)})
                seg_results.sort(key=lambda x: x['value'], reverse=True)
                result['segments'].append({
                    "segment_column": seg_col,
                    "metric_column": "customer_id",
                    "aggregation": "ratio",
                    "label": f"monthly_logo_churn_rate_{last_month.strftime('%Y-%m')}",
                    "results": seg_results
                })

    result['assumptions'].append("Monthly churn rate = customers lost in month M / customers active at end of M-1; only 'counted' row_kind rows used.")
    result['assumptions'].append("Active customer = customer_id with mrr > 0 in their latest snapshot for that month.")
    result['assumptions'].append("Last 12 months determined by the 12 most recent distinct month values in the dataset.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

