    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df['month'] = pd.to_datetime(df['month'])

    # Filter to counted rows only (exclude test, voided, etc.)
    df_valid = df[df['row_kind'] == 'counted'].copy() if 'row_kind' in df.columns else df.copy()

    # Get the 12 months window: last 12 distinct months in data
    all_months = sorted(df_valid['month'].dt.to_period('M').unique())
    last_12_months = all_months[-12:] if len(all_months) >= 12 else all_months

    df_valid['period'] = df_valid['month'].dt.to_period('M')

    monthly_churn_rates = []

    for i, period in enumerate(last_12_months):
        # Current month: customers paying (mrr > 0) at end of this month
        curr_month_df = df_valid[df_valid['period'] == period]
        # Each customer's latest snapshot in this period
        curr_snap = (
            curr_month_df.sort_values('month')
            .groupby('customer_id')
            .last()
            .reset_index()
        )
        curr_paying = set(curr_snap[curr_snap['mrr'] > 0]['customer_id'])

        # Previous month: customers paying at end of prior month
        if i == 0:
            # Need the month before the window
            prev_period = period - 1
            prev_month_df = df_valid[df_valid['period'] == prev_period]
        else:
            prev_period = last_12_months[i - 1]
            prev_month_df = df_valid[df_valid['period'] == prev_period]

        if len(prev_month_df) == 0:
            monthly_churn_rates.append({
                "period": str(period),
                "prev_paying_count": 0,
                "churned_count": 0,
                "churn_rate": None
            })
            continue

        prev_snap = (
            prev_month_df.sort_values('month')
            .groupby('customer_id')
            .last()
            .reset_index()
        )
        prev_paying = set(prev_snap[prev_snap['mrr'] > 0]['customer_id'])

        # Churned: were paying last month, not paying this month
        churned = prev_paying - curr_paying
        prev_count = len(prev_paying)
        churned_count = len(churned)
        churn_rate = churned_count / prev_count if prev_count > 0 else None

        monthly_churn_rates.append({
            "period": str(period),
            "prev_paying_count": prev_count,
            "churned_count": churned_count,
            "churn_rate": round(churn_rate, 4) if churn_rate is not None else None
        })

    # Store as segmentation result: monthly logo churn rate
    churn_segment_results = []
    for row in monthly_churn_rates:
        val = row['churn_rate'] if row['churn_rate'] is not None else float('nan')
        churn_segment_results.append({
            "name": row['period'],
            "value": round(val, 4) if not (val != val) else 0.0
        })

    result['segments'].append({
        "segment_column": "month",
        "metric_column": "customer_id",
        "aggregation": "ratio",
        "label": "monthly_logo_churn_rate",
        "results": churn_segment_results
    })

    # Also store churned count and prior paying count per month for transparency
    churned_count_results = []
    prev_paying_results = []
    for row in monthly_churn_rates:
        churned_count_results.append({
            "name": row['period'],
            "value": float(row['churned_count'])
        })
        prev_paying_results.append({
            "name": row['period'],
            "value": float(row['prev_paying_count'])
        })

    result['segments'].append({
        "segment_column": "month",
        "metric_column": "customer_id",
        "aggregation": "count",
        "label": "churned_customers_per_month",
        "results": churned_count_results
    })

    result['segments'].append({
        "segment_column": "month",
        "metric_column": "customer_id",
        "aggregation": "count",
        "label": "prior_month_paying_customers",
        "results": prev_paying_results
    })

    result['assumptions'].append(
        "Monthly logo churn rate = customers paying in month M-1 who have mrr=0 (or no row) in month M, divided by paying customers in M-1."
    )
    result['assumptions'].append(
        "Only 'counted' row_kind rows used; each customer's latest snapshot within the month is their month-end state."
    )
    result['assumptions'].append(
        "The 12-month window uses the last 12 calendar months present in the data; month 1 uses the preceding month as baseline."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "month",
        "metric_column": "customer_id",
        "aggregation": "ratio",
        "label": "monthly_logo_churn_rate",
        "results": [{"name": "error", "value": 0.0}]
    })
    result['assumptions'].append(f"Segmentation error: {str(e)}")

