    "assumptions": [],
}

try:
    import numpy as np
    df['month'] = pd.to_datetime(df['month'])

    # Get last two distinct months
    months_sorted = sorted(df['month'].unique())
    if len(months_sorted) >= 2:
        last_month = months_sorted[-1]
        prev_month = months_sorted[-2]

        # Per-account last value per month (already one row per account per month based on schema)
        def get_plan_mrr(month_val):
            sub = df[df['month'] == month_val]
            # last value per account_id in that month
            snap = sub.sort_values('month').groupby('account_id').last().reset_index()
            return snap.groupby('plan')['mrr'].sum()

        mrr_last = get_plan_mrr(last_month)
        mrr_prev = get_plan_mrr(prev_month)

        all_plans = mrr_last.index.union(mrr_prev.index)

        trend_entries = []
        seg_results = []

        for plan_name in all_plans:
            v_last = float(mrr_last.get(plan_name, 0.0))
            v_prev = float(mrr_prev.get(plan_name, 0.0))
            if v_prev > 0:
                pct = (v_last - v_prev) / v_prev * 100.0
            elif v_last > 0:
                pct = 100.0
            else:
                pct = 0.0
            direction = "up" if pct > 0.5 else ("down" if pct < -0.5 else "flat")
            trend_entries.append({
                "column": "mrr",
                "period": "MoM",
                "direction": direction,
                "pct_change": round(pct, 4),
                "segment": str(plan_name)
            })
            seg_results.append({"name": str(plan_name), "value": round(v_last, 2)})

        result['trends'] = trend_entries

        # Segmentation: MRR by plan for last month
        result['segments'].append({
            "segment_column": "plan",
            "metric_column": "mrr",
            "aggregation": "sum",
            "label": f"mrr_by_plan_{last_month.strftime('%Y-%m')}",
            "results": sorted(seg_results, key=lambda x: x['value'], reverse=True)
        })

        # Segmentation: MRR change (absolute) by plan MoM
        change_results = []
        for plan_name in all_plans:
            v_last = float(mrr_last.get(plan_name, 0.0))
            v_prev = float(mrr_prev.get(plan_name, 0.0))
            change_results.append({"name": str(plan_name), "value": round(v_last - v_prev, 2)})

        result['segments'].append({
            "segment_column": "plan",
            "metric_column": "mrr",
            "aggregation": "sum",
            "label": "mrr_mom_change_by_plan",
            "results": sorted(change_results, key=lambda x: abs(x['value']), reverse=True)
        })

        # Segmentation: MRR pct change by plan MoM
        pct_results = []
        for t in trend_entries:
            pct_results.append({"name": t['segment'], "value": round(t['pct_change'], 4)})

        result['segments'].append({
            "segment_column": "plan",
            "metric_column": "mrr",
            "aggregation": "ratio",
            "label": "mrr_mom_pct_change_by_plan",
            "results": sorted(pct_results, key=lambda x: abs(x['value']), reverse=True)
        })

except Exception as e:
    result['assumptions'].append(f"Trend/segmentation error: {str(e)}")

result['assumptions'].append("MRR per plan per month = sum of each account's last mrr value in that month, grouped by plan.")
