import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np
    df['month'] = pd.to_datetime(df['month'])

    # Get last two months in data
    months_sorted = sorted(df['month'].unique())
    if len(months_sorted) >= 2:
        last_month = months_sorted[-1]
        prev_month = months_sorted[-2]

        # Per-account last value per month (already one row per account per month based on schema)
        def month_mrr_by_plan(month_val):
            sub = df[df['month'] == month_val]
            return sub.groupby('plan')['mrr'].sum()

        mrr_last = month_mrr_by_plan(last_month)
        mrr_prev = month_mrr_by_plan(prev_month)

        plans_common = mrr_last.index.intersection(mrr_prev.index)

        plan_changes = {}
        for p in plans_common:
            prev_val = mrr_prev[p]
            last_val = mrr_last[p]
            if prev_val != 0:
                pct = (last_val - prev_val) / prev_val * 100
            else:
                pct = float('nan')
            plan_changes[p] = {"prev": float(prev_val), "last": float(last_val), "pct": float(pct) if not np.isnan(pct) else 0.0}

        # Find plan with largest absolute pct change
        max_plan = max(plan_changes, key=lambda p: abs(plan_changes[p]["pct"]))
        max_pct = plan_changes[max_plan]["pct"]

        trend_entries = []
        for p, vals in plan_changes.items():
            direction = "up" if vals["pct"] > 0 else ("down" if vals["pct"] < 0 else "flat")
            trend_entries.append({
                "column": "mrr",
                "period": "MoM",
                "direction": direction,
                "pct_change": round(vals["pct"], 4),
                "segment": p
            })

        result["trends"] = trend_entries

        # Segmentation: MRR by plan for last month
        seg_results = []
        for p in mrr_last.index:
            seg_results.append({"name": str(p), "value": round(float(mrr_last[p]), 2)})
        seg_results_sorted = sorted(seg_results, key=lambda x: x["value"], reverse=True)

        result["segments"] = [
            {
                "segment_column": "plan",
                "metric_column": "mrr",
                "aggregation": "sum",
                "label": f"mrr_by_plan_{last_month.strftime('%Y-%m')}",
                "results": seg_results_sorted
            }
        ]

        result["assumptions"] = [
            f"Last month is {last_month.strftime('%Y-%m')}, previous month is {prev_month.strftime('%Y-%m')}.",
            "MRR per plan = sum of mrr for all accounts in that plan for the given month (one row per account per month).",
            f"Plan with largest MoM MRR change: {max_plan} at {max_pct:.4f}%.",
            "pct_change is (last - prev) / prev * 100; plans only in one month are excluded.",
            "Trends computed only for plans present in both months."
        ]
    else:
        result["assumptions"] = ["Fewer than 2 distinct months in data; MoM trend cannot be computed."]
except Exception as e:
    result["assumptions"] = [f"Trend/segmentation error: {str(e)}"]

