        # Per-account last value per month (level semantics)
        df['month_period'] = df['month'].dt.to_period('M')

        snap = df.sort_values('month').groupby(['account_id', 'month_period', 'plan']).last().reset_index()

        # MRR by plan for last two months
        last_snap = snap[snap['month_period'] == last_month].groupby('plan')['mrr'].sum()
        prev_snap = snap[snap['month_period'] == prev_month].groupby('plan')['mrr'].sum()

        plans = last_snap.index.union(prev_snap.index)

        plan_changes = []
        for p in plans:
            v_last = last_snap.get(p, 0.0)
            v_prev = prev_snap.get(p, 0.0)
            if v_prev > 0:
                pct = (v_last - v_prev) / v_prev * 100
            else:
                pct = float('nan')
            plan_changes.append((p, v_prev, v_last, pct))

