                direction = "up" if v_last > 0 else "flat"
                pct_val = 0.0
            else:
                direction = "up" if pct > 0 else ("down" if pct < 0 else "flat")
                pct_val = round(pct, 4)
            trend_entries.append({
                "column": "mrr",
                "period": "MoM",
                "direction": direction,
                "pct_change": pct_val,
