import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # NRR by segment using domain facts:
    # NRR = MRR at latest date of customers paying 12 months earlier / their MRR then
    # Domain facts give overall NRR = 91.1% for 12 months to 31 Oct 2026
    # We compute per-segment NRR from the data using in_force_now and window columns

    df['month_dt'] = pd.to_datetime(df['month'])

    # Identify the latest month and the month 12 months prior
    latest_month = df['month_dt'].max()
    prior_month = latest_month - pd.DateOffset(months=12)

    # Find the prior month snapshot (customers paying ~12 months ago)
    # Use rows closest to prior_month
    prior_months = df['month_dt'].unique()
    prior_months_sorted = sorted(prior_months)

    # Find month closest to 12 months before latest
    prior_snap = min(prior_months_sorted, key=lambda m: abs((m - prior_month).days))
    latest_snap = latest_month

    # Cohort: customers paying at prior snapshot
    prior_df = df[df['month_dt'] == prior_snap][['customer_id', 'mrr', 'segment']].copy()
    prior_df = prior_df.groupby(['customer_id', 'segment'], as_index=False)['mrr'].sum()
    prior_df = prior_df[prior_df['mrr'] > 0]

    # Latest snapshot MRR for those same customers
    latest_df = df[df['month_dt'] == latest_snap][['customer_id', 'mrr']].copy()
    latest_df = latest_df.groupby('customer_id', as_index=False)['mrr'].sum()
    latest_df = latest_df[latest_df['mrr'] > 0]

    # Merge: keep only customers in prior cohort, get their current MRR (0 if churned)
    cohort = prior_df.merge(latest_df, on='customer_id', how='left', suffixes=('_prior', '_latest'))
    cohort['mrr_latest'] = cohort['mrr_latest'].fillna(0.0)

    # NRR per segment = sum(mrr_latest for cohort customers) / sum(mrr_prior for cohort customers)
    seg_nrr = cohort.groupby('segment').agg(
        mrr_prior=('mrr_prior', 'sum'),
        mrr_latest=('mrr_latest', 'sum')
    ).reset_index()
    seg_nrr['nrr'] = seg_nrr['mrr_latest'] / seg_nrr['mrr_prior']

    nrr_results = [
        {"name": row['segment'], "value": round(float(row['nrr']), 4)}
        for _, row in seg_nrr.iterrows()
    ]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "ratio",
        "label": "net_revenue_retention",
        "results": nrr_results
    })

    # Also provide MRR at latest date by segment (in_force_now if available, else latest snap)
    if 'in_force_now' in df.columns:
        current_mrr = df[df['in_force_now'] == 'yes'].groupby('segment')['mrr'].sum().reset_index()
    else:
        current_mrr = df[df['month_dt'] == latest_snap].groupby('segment')['mrr'].sum().reset_index()

    current_results = [
        {"name": str(row['segment']), "value": round(float(row['mrr']), 2)}
        for _, row in current_mrr.iterrows()
    ]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "sum",
        "label": "current_mrr_by_segment",
        "results": current_results
    })

    # Prior MRR by segment (cohort baseline)
    prior_results = [
        {"name": str(row['segment']), "value": round(float(row['mrr_prior']), 2)}
        for _, row in seg_nrr.iterrows()
    ]

