    "assumptions": [],
}

try:
    import numpy as np

    # NRR by segment using domain facts:
    # NRR = MRR at latest date of customers paying 12 months earlier / their MRR then
    # Domain facts give overall NRR = 91.1% for 12 months to 31 Oct 2026
    # We need per-segment NRR from the data

    df['month_dt'] = pd.to_datetime(df['month'])

    # Use only counted rows
    df_counted = df[df['row_kind'] == 'counted'].copy()

    # Latest month in data
    latest_month = df_counted['month_dt'].max()
    # 12 months earlier
    earlier_month = latest_month - pd.DateOffset(months=12)

    # Find the month-end snapshots closest to latest and 12 months earlier
    months_available = sorted(df_counted['month_dt'].unique())

    # Get the snapshot at latest month
    df_latest = df_counted[df_counted['month_dt'] == latest_month][['customer_id', 'mrr', 'segment']].copy()
    df_latest = df_latest.sort_values('mrr', ascending=False).drop_duplicates('customer_id')

    # Get snapshot at 12 months earlier (find closest month to earlier_month)
    earlier_months = [m for m in months_available if abs((m - earlier_month).days) <= 31]
    if earlier_months:
        earlier_snap_month = min(earlier_months, key=lambda m: abs((m - earlier_month).days))
    else:
        earlier_snap_month = months_available[0]

    df_earlier = df_counted[df_counted['month_dt'] == earlier_snap_month][['customer_id', 'mrr', 'segment']].copy()
    df_earlier = df_earlier.sort_values('mrr', ascending=False).drop_duplicates('customer_id')
    df_earlier = df_earlier.rename(columns={'mrr': 'mrr_earlier', 'segment': 'segment_earlier'})

    # Cohort: customers paying at earlier snapshot
    cohort = df_earlier[df_earlier['mrr_earlier'] > 0].copy()

    # Join to latest snapshot (mrr=0 if not present = churned)
    merged = cohort.merge(df_latest[['customer_id', 'mrr', 'segment']], on='customer_id', how='left')
    merged['mrr'] = merged['mrr'].fillna(0.0)
    merged['segment'] = merged['segment'].fillna(merged['segment_earlier'])

    # NRR by segment: sum(current mrr) / sum(earlier mrr) per segment
    seg_nrr = merged.groupby('segment_earlier').agg(
        mrr_now=('mrr', 'sum'),
        mrr_base=('mrr_earlier', 'sum')
    ).reset_index()
    seg_nrr['nrr'] = seg_nrr['mrr_now'] / seg_nrr['mrr_base']

    nrr_results = [
        {"name": row['segment_earlier'], "value": round(float(row['nrr']), 4)}
        for _, row in seg_nrr.iterrows()
    ]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "ratio",
        "label": "net_revenue_retention",
        "results": nrr_results
    })

    # Also provide MRR at latest date by segment (in_force_now if available, else latest month)
    if 'in_force_now' in df.columns:
        df_inforce = df[(df['in_force_now'] == 'yes') & (df['row_kind'] == 'counted')]
    else:
        df_inforce = df_counted[df_counted['month_dt'] == latest_month]

    mrr_by_seg = df_inforce.groupby('segment')['mrr'].sum().reset_index()
    mrr_results = [
        {"name": str(row['segment']), "value": round(float(row['mrr']), 2)}
        for _, row in mrr_by_seg.iterrows()
    ]
    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "sum",
        "label": "mrr_current",
        "results": mrr_results
    })

    # Customer count by segment in cohort (paying 12 months ago)
    cohort_count = cohort.groupby('segment_earlier').size().reset_index(name='count')
    count_results = [
        {"name": str(row['segment_earlier']), "value": float(row['count'])}
        for _, row in cohort_count.iterrows()
    ]
    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "customer_id",
        "aggregation": "count",
        "label": "cohort_customers_12m_ago",
        "results": count_results
    })

    result['assumptions'].append(
        f"NRR computed as sum(current mrr) / sum(mrr at {earlier_snap_month.date()}) for customers paying at that snapshot; overall NRR per domain facts is 91.1%."
    )
    result['assumptions'].append(
        "Segment label taken from the earlier snapshot for churned customers (mrr=0 at latest date)."
    )
    result['assumptions'].append(
        "Only rows with row_kind='counted' used; latest snapshot month is the maximum month in the dataset."
    )

