    # NRR by segment, 12-month window: Nov 2025 – Oct 2026
    # Cohort: customers paying 12 months before the latest date (i.e., paying in Oct 2025 / Nov 2025 window)
    # Per domain rules: NRR = sum of mrr at latest date for those customers / their mrr 12 months earlier

    df['month_dt'] = pd.to_datetime(df['month'])

    # Latest date in data
    latest_month = df['month_dt'].max()
    # 12 months earlier
    earlier_month = latest_month - pd.DateOffset(months=12)

    # Filter to counted rows only
    df_counted = df[df['row_kind'] == 'counted'].copy()

    # Snapshot at latest month: each customer's mrr at latest month
    snap_latest = df_counted[df_counted['month_dt'] == latest_month][['customer_id', 'mrr', 'segment']].copy()
    snap_latest = snap_latest.sort_values('mrr', ascending=False).drop_duplicates('customer_id')

    # Snapshot at earlier month (12 months ago)
    snap_earlier = df_counted[df_counted['month_dt'] == earlier_month][['customer_id', 'mrr', 'segment']].copy()
    snap_earlier = snap_earlier.sort_values('mrr', ascending=False).drop_duplicates('customer_id')
    snap_earlier = snap_earlier[snap_earlier['mrr'] > 0]

    # Cohort: customers paying 12 months ago
    cohort_ids = set(snap_earlier['customer_id'])

    # Their MRR at latest date (0 if churned)
    snap_latest_cohort = snap_latest[snap_latest['customer_id'].isin(cohort_ids)][['customer_id', 'mrr']].copy()
    snap_latest_cohort.columns = ['customer_id', 'mrr_now']

    # Merge with earlier snapshot to get segment and earlier mrr
    merged = snap_earlier.merge(snap_latest_cohort, on='customer_id', how='left')
    merged['mrr_now'] = merged['mrr_now'].fillna(0.0)

    # NRR by segment
    seg_nrr = merged.groupby('segment').apply(
        lambda g: g['mrr_now'].sum() / g['mrr'].sum() if g['mrr'].sum() > 0 else np.nan
    ).reset_index()
    seg_nrr.columns = ['segment', 'nrr']

    nrr_results = [{"name": row['segment'], "value": round(float(row['nrr']), 4)}
                   for _, row in seg_nrr.iterrows() if not np.isnan(row['nrr'])]

    # Overall NRR for reference
    overall_nrr = merged['mrr_now'].sum() / merged['mrr'].sum() if merged['mrr'].sum() > 0 else np.nan

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "ratio",
        "label": "net_revenue_retention",
        "results": nrr_results
    })

    # Also provide MRR at latest date by segment (in-force customers only)
    in_force = df_counted[df_counted.get('in_force_now', pd.Series(dtype=str)) == 'yes'] if 'in_force_now' in df_counted.columns else snap_latest
    if 'in_force_now' in df_counted.columns:
        in_force_snap = df_counted[df_counted['in_force_now'] == 'yes'][['customer_id', 'mrr', 'segment']].drop_duplicates('customer_id')
    else:
        in_force_snap = snap_latest

    mrr_by_seg = in_force_snap.groupby('segment')['mrr'].sum().reset_index()
    mrr_results = [{"name": row['segment'], "value": round(float(row['mrr']), 2)}
                   for _, row in mrr_by_seg.iterrows()]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "sum",
        "label": "mrr_at_latest_date",
        "results": mrr_results
    })

    # Cohort size by segment
    cohort_by_seg = snap_earlier.groupby('segment')['customer_id'].count().reset_index()
    cohort_results = [{"name": row['segment'], "value": int(row['customer_id'])}
                      for _, row in cohort_by_seg.iterrows()]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "customer_id",
        "aggregation": "count",
        "label": "cohort_size_12m_ago",
        "results": cohort_results
    })

    result['assumptions'].append(
        f"NRR cohort = customers with mrr>0 at {earlier_month.strftime('%Y-%m')}; "
        f"overall NRR={overall_nrr:.3f} (domain fact: 0.911); "
        "segment uses each customer's segment at the earlier snapshot."
    )
    result['assumptions'].append(
        "Only 'counted' row_kind rows used; mrr deduplicated per customer per month by taking highest-mrr row."
    )
    result['assumptions'].append(
        "MRR at latest date for churned cohort members set to 0 (left-join, fillna 0)."
    )

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

