import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df_work = df.copy()
    df_work['month'] = pd.to_datetime(df_work['month'])

    # Filter to last 12 months window: Nov 2025 – Oct 2026
    window_start = pd.Timestamp('2025-11-01')
    window_end = pd.Timestamp('2026-10-31')
    df_win = df_work[(df_work['month'] >= window_start) & (df_work['month'] <= window_end)].copy()

    # For each customer, get their MRR per month-end (last value by month)
    df_win['month_period'] = df_win['month'].dt.to_period('M')

    # Sort and get last row per customer per month
    df_snap = (
        df_win.sort_values('month')
        .groupby(['month_period', 'customer_id'], as_index=False)
        .last()
    )

    # Identify churn events: customer had mrr > 0 in month M, then mrr == 0 (or absent) in month M+1
    # Build pivot: customer x month MRR
    all_months = sorted(df_snap['month_period'].unique())
    pivot = df_snap.pivot_table(index='customer_id', columns='month_period', values='mrr', aggfunc='last')

    churned_mrr_by_month = {}
    for i in range(1, len(all_months)):
        prev_m = all_months[i - 1]
        curr_m = all_months[i]
        if prev_m not in pivot.columns or curr_m not in pivot.columns:
            continue
        prev_mrr = pivot[prev_m].fillna(0)
        curr_mrr = pivot[curr_m].fillna(0)
        # Churned: had mrr > 0 in prev month, mrr == 0 (or missing) in current month
        churned_mask = (prev_mrr > 0) & (curr_mrr == 0)
        churned_mrr = prev_mrr[churned_mask].sum()
        churned_mrr_by_month[str(curr_m)] = round(float(churned_mrr), 2)

    # Also get segment info for churned customers per month
    # Build segment lookup: customer -> segment (last known)
    seg_lookup = df_snap.sort_values('month').groupby('customer_id')['segment'].last()

    churned_by_segment = {}
    for i in range(1, len(all_months)):
        prev_m = all_months[i - 1]
        curr_m = all_months[i]
        if prev_m not in pivot.columns or curr_m not in pivot.columns:
            continue
        prev_mrr = pivot[prev_m].fillna(0)
        curr_mrr = pivot[curr_m].fillna(0)
        churned_mask = (prev_mrr > 0) & (curr_mrr == 0)
        churned_custs = prev_mrr[churned_mask].index
        for cust in churned_custs:
            seg = seg_lookup.get(cust, 'Unknown')
            key = (str(curr_m), seg)
            churned_by_segment[key] = churned_by_segment.get(key, 0.0) + float(prev_mrr[cust])

    # Segment 1: Churned MRR by month
    month_results = [{"name": m, "value": v} for m, v in sorted(churned_mrr_by_month.items())]

    # Segment 2: Churned MRR by segment (aggregated over window)
    seg_totals = {}
    for (m, seg), v in churned_by_segment.items():
        seg_totals[seg] = seg_totals.get(seg, 0.0) + v
    seg_results = [{"name": s, "value": round(v, 2)} for s, v in sorted(seg_totals.items(), key=lambda x: -x[1])]

    # Segment 3: Churned MRR by month x segment (two-column breakdown)
    combo_results = []
    for (m, seg), v in sorted(churned_by_segment.items(), key=lambda x: (-x[1][0] if False else x[0][0])):
        combo_results.append({"name": f"{m}|{seg}", "value": round(v, 2)})
    combo_results = sorted(combo_results, key=lambda x: x['name'])

    result['segments'] = [
        {
            "segment_column": "month",
            "metric_column": "mrr",
            "aggregation": "sum",
            "label": "churned_mrr_by_month",
            "results": month_results
        },
        {
            "segment_column": "segment",
            "metric_column": "mrr",
            "aggregation": "sum",
            "label": "churned_mrr_by_segment",
            "results": seg_results
        },
        {
            "segment_column": "month|segment",
            "metric_column": "mrr",
            "aggregation": "sum",
            "label": "churned_mrr_month_x_segment",
            "results": combo_results
        }
    ]

    result['assumptions'] = [
        "Churn defined as: customer had mrr > 0 at a month-end, then mrr = 0 or absent the next month-end.",
        "Window: Nov 2025 – Oct 2026 (12 months); churned MRR attributed to the month the customer left.",
        "Per-customer monthly MRR = last row value in that month (snapshot semantics).",
        "Segment assigned from customer's last known segment in the window.",
        "Churned MRR by month reflects MRR lost entering that month (i.e., lost between prev and curr month-end)."
    ]

except Exception as e:
    result['assumptions'] = [f"Segmentation error: {str(e)}"]

