import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df_work = df.copy()
    df_work['month'] = pd.to_datetime(df_work['month'])

    # Filter to last 12 months window: Nov 2025 – Oct 2026
    window_start = pd.Timestamp('2025-11-01')
    window_end = pd.Timestamp('2026-10-31')
    df_win = df_work[(df_work['month'] >= window_start) & (df_work['month'] <= window_end)].copy()

    # For each customer, get their MRR per month-end (last value by month)
    df_win['month_period'] = df_win['month'].dt.to_period('M')

    # Sort and deduplicate to get last snapshot per customer per month
    df_snap = (
        df_win.sort_values('month')
        .groupby(['month_period', 'customer_id'], as_index=False)
        .last()
    )

    # Build month-over-month MRR per customer to detect churn moves (mrr -> 0)
    # We need Oct 2025 as the prior month baseline
    oct2025 = pd.Timestamp('2025-10-01')
    df_prior = df_work[df_work['month'] == oct2025].copy()
    df_prior['month_period'] = df_prior['month'].dt.to_period('M')
    df_prior_snap = (
        df_prior.sort_values('month')
        .groupby(['month_period', 'customer_id'], as_index=False)
        .last()
    )

    # Combine prior + window snapshots
    df_all_snap = pd.concat([df_prior_snap, df_snap], ignore_index=True)
    df_all_snap = df_all_snap.sort_values(['customer_id', 'month_period'])

    # Pivot: customers x months
    pivot = df_all_snap.pivot_table(
        index='customer_id', columns='month_period', values='mrr', aggfunc='last'
    )

    all_periods = sorted(pivot.columns)
    window_periods = [p for p in all_periods if p >= pd.Period('2025-11', 'M')]

    churned_mrr_by_month = {}
    for i, period in enumerate(window_periods):
        if i == 0:
            prev_period = pd.Period('2025-10', 'M')
        else:
            prev_period = window_periods[i - 1]

        if prev_period not in pivot.columns:
            churned_mrr_by_month[str(period)] = 0.0
            continue

        prev_mrr = pivot[prev_period].fillna(0)
        curr_mrr = pivot[period].fillna(0) if period in pivot.columns else pd.Series(0, index=pivot.index)

        # Churn: had mrr > 0 in prev, now 0 (or absent)
        churn_mask = (prev_mrr > 0) & (curr_mrr == 0)
        churned_mrr_by_month[str(period)] = float(prev_mrr[churn_mask].sum())

    # Build segment results
    churn_results = [
        {"name": period_str, "value": round(val, 2)}
        for period_str, val in churned_mrr_by_month.items()
    ]

    result['segments'].append({
        "segment_column": "month",
        "metric_column": "mrr",
        "aggregation": "sum",
        "label": "churned_mrr_per_month",
        "results": churn_results
    })

    # Also break down churned MRR by segment column for the window
    for seg_col in ['plan', 'segment', 'country']:
        seg_churn = {}
        for i, period in enumerate(window_periods):
            if i == 0:
                prev_period = pd.Period('2025-10', 'M')
            else:
                prev_period = window_periods[i - 1]

            if prev_period not in pivot.columns:
                continue

            prev_mrr = pivot[prev_period].fillna(0)
            curr_mrr = pivot[period].fillna(0) if period in pivot.columns else pd.Series(0, index=pivot.index)
            churn_mask = (prev_mrr > 0) & (curr_mrr == 0)
            churned_customers = prev_mrr[churn_mask].index.tolist()

            if not churned_customers:
                continue

            # Get segment label for churned customers from prior snapshot
            prior_rows = df_all_snap[
                (df_all_snap['month_period'] == prev_period) &
                (df_all_snap['customer_id'].isin(churned_customers))
            ][['customer_id', seg_col, 'mrr']].copy()

            for _, row in prior_rows.iterrows():
                key = str(row[seg_col])
                seg_churn[key] = seg_churn.get(key, 0.0) + float(row['mrr'])

        seg_results = [
            {"name": k, "value": round(v, 2)}
            for k, v in sorted(seg_churn.items(), key=lambda x: -x[1])
        ]
        if seg_results:
            result['segments'].append({
                "segment_column": seg_col,
                "metric_column": "mrr",
                "aggregation": "sum",
                "label": "churned_mrr_12m",
                "results": seg_results
            })

    result['assumptions'].append("Churn move: customer MRR > 0 in month T-1 and 0 (or absent) in month T.")
    result['assumptions'].append("Window: Nov 2025 – Oct 2026; Oct 2025 used as baseline prior month.")
    result['assumptions'].append("Per-month MRR = last snapshot per customer per month-end.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

