import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    billing_df = df[~df['status'].isin(['void', 'voided', 'draft', 'deleted'])].copy()
    billing_df['invoice_date'] = pd.to_datetime(billing_df['invoice_date'])
    billing_df['month'] = billing_df['invoice_date'].dt.to_period('M')

    monthly = billing_df.groupby('month')['amount'].sum().reset_index()
    monthly['month_str'] = monthly['month'].astype(str)

    result['segments'].append({
        "segment_column": "invoice_date",
        "metric_column": "amount",
        "aggregation": "sum",
        "label": "billings_by_month",
        "results": [
            {"name": row['month_str'], "value": float(row['amount'])}
            for _, row in monthly.iterrows()
        ]
    })
except Exception as e:
    result['segments'].append({
        "segment_column": "invoice_date",
        "metric_column": "amount",
        "aggregation": "sum",
        "label": "billings_by_month",
        "results": [{"name": "error", "value": 0.0}]
    })

try:
    for seg_col in ['line_type', 'status', 'currency']:
        seg_monthly = billing_df.groupby([billing_df['invoice_date'].dt.to_period('M').astype(str), seg_col])['amount'].sum().reset_index()
        seg_monthly.columns = ['month', seg_col, 'amount']
        seg_monthly['name'] = seg_monthly['month'] + '|' + seg_monthly[seg_col].astype(str)
        result['segments'].append({
            "segment_column": f"invoice_date|{seg_col}",
            "metric_column": "amount",
            "aggregation": "sum",
            "label": f"billings_by_month_{seg_col}",
            "results": [
                {"name": row['name'], "value": float(row['amount'])}
                for _, row in seg_monthly.iterrows()
            ]
        })
except Exception:
    pass

try:
    n_months = len(monthly)
    if n_months >= 2:
        last = float(monthly.iloc[-1]['amount'])
        prev = float(monthly.iloc[-2]['amount'])
        pct = ((last - prev) / abs(prev) * 100) if prev != 0 else 0.0
        direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
        result['trends'].append({
            "column": "amount",
            "period": "MoM",
            "direction": direction,
            "pct_change": round(pct, 4),
            "segment": None
        })
except Exception:
    pass

result['assumptions'].append("Billings = sum of amount excluding void/voided/draft/deleted invoices, by invoice_date month.")
result['assumptions'].append("Credit notes (negative amounts) are netted within each month.")
result['assumptions'].append("Month labels are calendar months derived from invoice_date.")

